    minVersionCode: Int,
    latestVersionCode: Int,
    latestVersionName: String,
    forceUpdate: Boolean,
    title: String?,
    message: String?,
    storeUrl: String?,
    titleVi: String? = null,
    titleEn: String? = null,
    messageVi: String? = null,
    messageEn: String? = null,
): AppConfig = withContext(Dispatchers.IO) {
    val updated = try {
        supabase.postgrest
            .rpc(
