    val dirA = PrivateScreenshotDiskCache.accountDir(context, "user-a")
    dirA.mkdirs()
    val fileA = java.io.File(dirA, "entry.bin").apply { writeBytes(byteArrayOf(1, 2, 3)) }
    assertTrue(fileA.exists())

