            assertFalse(vm.uiState.value.isActionLoading)
        } finally {
            client.close()
        }
    }

    @Test
    fun preNetworkGuard_unauthenticatedAdmin_rejectsImmediately() = runBlocking {
        var deleteCalls = 0
